import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        StringBuilder sb = new StringBuilder();
        for (int k = 0; k < n; k++) {
            String s = next();
            // Chairs needed = peak number of people inside the room.
            int inside = 0, best = 0;
            for (int i = 0; i < s.length(); i++) {
                char e = s.charAt(i);
                if (e == 'C' || e == 'U') inside++;
                else inside--;
                best = Math.max(best, inside);
            }
            if (k > 0) sb.append(' ');
            sb.append(best);
        }
        sb.append('\n');
        System.out.print(sb);
    }
}

package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func nextToken() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	var out []byte
	for k := 0; k < n; k++ {
		s := nextToken()
		// Chairs needed = peak number of people inside the room.
		inside, best := 0, 0
		for i := 0; i < len(s); i++ {
			if s[i] == 'C' || s[i] == 'U' {
				inside++
			} else {
				inside--
			}
			best = max(best, inside)
		}
		if k > 0 {
			out = append(out, ' ')
		}
		out = strconv.AppendInt(out, int64(best), 10)
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
